func ValidIPv4(s string) bool {
    parts := strings.Split(s, ".")
    if len(parts) != 4 {
        return false
    }
    for _, p := range parts {
        if p == "" || (len(p) > 1 && p[0] == '0') {
            return false
        }
        n := 0
        for i := 0; i < len(p); i++ {
            if p[i] < '0' || p[i] > '9' {
                return false
            }
            n = n*10 + int(p[i]-'0')
            if n > 255 {
                return false
            }
        }
    }
    return true
}
